appearances.css:
.app{padding:5px 6px 6px;border-radius:4px;font-size:9px}
.row{gap:4px;margin:3px 0}
.control{padding:0;border:0;border-radius:0}
.row>.control{flex:1 1 90px;gap:1px}
.row>.control span{font-size:7.5px;letter-spacing:.04em;text-transform:uppercase}

.row>.control:only-child{flex:0 1 150px}
select{font-size:10px;padding:3px 4px;border-radius:3px;width:100%}
.row button{font-size:10px;padding:3px 6px;border-radius:3px;flex:1 1 auto}
canvas{border-radius:3px}
canvas:first-of-type{height:70px!important}
canvas:last-of-type{height:34px!important}
p{margin:2px 0;font-size:9px;line-height:1.2}
.grid{grid-template-columns:repeat(auto-fit,minmax(60px,1fr));gap:2px 0;margin:3px 0;padding:3px 2px 4px;border:1px solid var(--line,#344953);border-radius:3px}
.control:has(.kn){display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0}
.control:has(.kn)>span:not(.kn){order:3;font-size:7.5px;letter-spacing:-.02em;text-align:center;max-width:100%;line-height:1.1;white-space:normal;color:var(--muted,#adc3c9)}
.control:has(.kn)>output{order:2;font-size:8px;text-align:center;line-height:1.1}
.control .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
